lessons.solution_code:
def safe_dispatch(name, args, registry):
    if name not in registry:
        return {'error': 'unknown tool: ' + name}
    return {'result': registry[name](**args)}

tests.unittest_code:
def test_safe_dispatch(self):
    reg = {'ping': lambda: 'pong'}
    self.assertEqual(safe_dispatch('ping', {}, reg), {'result': 'pong'})
    self.assertIn('error', safe_dispatch('nope', {}, reg))
